-- Global catalog of data systems for UI (connections, routing, pipelines).
CREATE TABLE IF NOT EXISTS data_systems (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    slug TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    category TEXT NOT NULL,
    tagline TEXT NOT NULL,
    accent TEXT NOT NULL DEFAULT 'from-slate-400/30 to-slate-600/10',
    sort_order INT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_data_systems_sort ON data_systems (sort_order, name);

ON CONFLICT (slug) DO NOTHING;
